import{_ as a,o,c as s,a2 as t}from"./chunks/framework.BM5YPQmL.js";const _=JSON.parse('{"title":"共享对象加载器","description":"","frontmatter":{},"headers":[],"relativePath":"zh/l1/solib-loader.md","filePath":"zh/l1/solib-loader.md"}'),l={name:"zh/l1/solib-loader.md"};function d(n,e,i,c,r,p){return o(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="共享对象加载器" tabindex="-1">共享对象加载器 <a class="header-anchor" href="#共享对象加载器" aria-label="Permalink to &quot;共享对象加载器&quot;">​</a></h1><p><code>ocos/l1apps/ld_so.c</code> - 树内动态加载器（本身是一个 ring-3 程序， 经 <code>ld_so.ld</code> 链接在 0x10000000），供动态链接的用户程序使用。</p><h2 id="它处理什么" tabindex="-1">它处理什么 <a class="header-anchor" href="#它处理什么" aria-label="Permalink to &quot;它处理什么&quot;">​</a></h2><p>ELF 动态对象：DT_NEEDED 链、符号表、重定位处理 （R_X86_64_RELATIVE / GLOB_DAT / JUMP_SLOT / 64 各族）、加载时 的 init 数组，以及带引用处理的卸载。</p><h2 id="镜像模式" tabindex="-1">镜像模式 <a class="header-anchor" href="#镜像模式" aria-label="Permalink to &quot;镜像模式&quot;">​</a></h2><p><code>tools/gen_userprogs.py</code> 按程序保留 v2.x 的构建模式：静态应用 用 ET_EXEC，<code>dyn_hello</code> / <code>pie_test</code> / <code>so_test</code> / <code>dlsym_test</code> / <code>reloc_test</code> 用 ET_DYN + <code>PT_INTERP=/lib/ld.so</code>（内核拒绝把 PIE 程序静默降级为 ET_EXEC - 镜像类型是接口的一部分）。</p><h2 id="它能工作的证据" tabindex="-1">它能工作的证据 <a class="header-anchor" href="#它能工作的证据" aria-label="Permalink to &quot;它能工作的证据&quot;">​</a></h2><p>内嵌机队从 ring 3 演练每个角落：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; run dyn_hello           (loaded, init ran, hello printed)</span></span>
<span class="line"><span>ush&gt; run so_test             (foo_add(2,3)=5 through the solib)</span></span>
<span class="line"><span>ush&gt; run dlsym_test          (dlsym resolves foo_add(7,8)=15)</span></span>
<span class="line"><span>ush&gt; run pie_test            (loaded at 0x... - PIE base assignment)</span></span>
<span class="line"><span>ush&gt; run reloc_test          (foo_add=30 foo_global=42 fp=300)</span></span></code></pre></div><p>外加 <code>l1test</code> 的 <code>ext_wp8b selftest 14/14</code> - 搭乘每次回归运行的 加载器自检。如果你的程序经这条路径加载，这些就是你的回归 锚点。</p><h2 id="位置无关" tabindex="-1">位置无关 <a class="header-anchor" href="#位置无关" aria-label="Permalink to &quot;位置无关&quot;">​</a></h2><p>PIE 对象经同一套重定位流程重定位；加载器的基址分配让 <code>-fno-pie</code> 应用与 PIE 程序共存于一个注册表 - <code>pie_test</code> 的 源码展示了一个动态程序可能携带的确切重定位组合。</p><h2 id="libfoo-这一环" tabindex="-1">libfoo 这一环 <a class="header-anchor" href="#libfoo-这一环" aria-label="Permalink to &quot;libfoo 这一环&quot;">​</a></h2><p><code>libfoo.c</code>（内嵌 solib）由 <code>tools/build_solib.py</code> 构建进 <code>solib_data.h</code> - 与其他每个程序相同的内嵌链，因此过期门禁 同样覆盖它。</p>`,14)])])}const b=a(l,[["render",d]]);export{_ as __pageData,b as default};
